Set_Is_Constrained     (Def_Id, not Is_FLB_Array_Subtype);
Set_Is_Fixed_Lower_Bound_Array_Subtype
                       (Def_Id, Is_FLB_Array_Subtype);
Set_Is_Aliased         (Def_Id, Is_Aliased (T));
Set_Is_Independent     (Def_Id, Is_Independent (T));
